/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountShareInvite, type ShareInviteOptions } from "../../components/share-invite/ShareInviteEngine.js";
import type { MotionController } from "../../components/share-invite/motion-runtime";

export function ShareInvite({ options, className }: { options?: ShareInviteOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountShareInvite(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="share-invite" />;
}

